-- STORELIB DATABASE, FILE 3 of 3
-- Old page views placed on the property they were seen on (the last step of part 61), the storage.objects policies (seven consolidated ones), then one row of true or false, one column per part.
-- HOW: select all of this file, copy, paste into a NEW query tab in the Supabase
-- SQL editor, press Run. Run the three files in order, one at a time.
-- Safe to run again: every statement checks before it changes anything, so a
-- second run changes nothing. If Run shows an error, stop and send it; the
-- editor runs the paste as one transaction, so nothing in this file changed.
-- Built from supabase/sql/run-now/ (one statement per line, text unchanged).

set local statement_timeout = 0;
-- the record of which parts ran (part 67)
CREATE TABLE IF NOT EXISTS public.storelib_applied_parts (part text PRIMARY KEY, file text NOT NULL, sha256 text NOT NULL, applied_at timestamptz NOT NULL DEFAULT now(), applied_by text NOT NULL DEFAULT current_user);
ALTER TABLE public.storelib_applied_parts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.storelib_applied_parts FROM anon, authenticated;

-- part 61_analytics_one_pipeline.sql, its last step, here on its own so that no order waits for it (see README.md): old page views placed on the property they were seen on. About a minute per million page views; a second run changes nothing.
DO $$ DECLARE has_purpose boolean; creator_hosts text := $h$ ('storelib.com', 'www.storelib.com', 'localhost', '127.0.0.1') $h$; v_rows bigint; BEGIN has_purpose := EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'custom_domains' AND column_name = 'purpose'); EXECUTE format($q$ WITH sole AS (SELECT creator_id, (array_agg(id))[1] AS install_id FROM public.store_theme_installs GROUP BY creator_id HAVING count(*) = 1), placed AS ( SELECT e.id, e.creator_id, %1$s AS host FROM public.analytics_events e WHERE e.property_type IS NULL AND e.event_type = 'view' AND e.page_url ~* '^https?://[^/?#]+' ), typed AS ( SELECT p.id, p.creator_id, CASE WHEN p.host IN %2$s OR p.host LIKE '%%.vercel.app' THEN 'creator_page' WHEN %3$s THEN 'creator_page' ELSE 'website' END AS property_type FROM placed p WHERE p.host IS NOT NULL ) UPDATE public.analytics_events e SET property_type = t.property_type, property_id = CASE WHEN t.property_type = 'website' THEN (SELECT s.install_id FROM sole s WHERE s.creator_id = t.creator_id) END FROM typed t WHERE e.id = t.id AND e.property_type IS NULL $q$, 'lower(substring(e.page_url from ''^[a-zA-Z][a-zA-Z0-9+.-]*://([^/?#:]+)''))', creator_hosts, CASE WHEN has_purpose THEN $c$EXISTS (SELECT 1 FROM public.custom_domains d WHERE d.creator_id = p.creator_id AND d.domain = regexp_replace(p.host, '^www\.', '') AND d.purpose = 'creator_page')$c$ ELSE 'false' END); GET DIAGNOSTICS v_rows = ROW_COUNT; RAISE NOTICE 'analytics_events: % old page views placed on a property', v_rows; END $$;

-- part 90_storage_policies_needs_owner.sql, with a first step that skips it (a notice, not an error) when this role does not own storage.objects
/* LAST, ON ITS OWN. Replaces the storage.objects policies. Needs the owner of storage.objects; see README if it says "must be owner". */
do $$ declare private_buckets text[] := array['digital-products', 'product-files', 'digital-assets']; public_buckets text[] := array['product-images', 'avatars', 'covers', 'store-builder-images', 'onepage-assets', 'lead-form-files-v2', 'lead-form-files', 'product-videos', 'email-images']; managed text[]; public_list text; owner_expr text; pol record; b text; mentions text; unmanaged text; begin if not pg_has_role(current_user, (select c.relowner from pg_class c where c.oid = 'storage.objects'::regclass), 'MEMBER') then raise notice 'storage policies skipped: this role does not own storage.objects, so they were left as they are. Everything else ran. See supabase/sql/run-four/README.md.'; return; end if; managed := private_buckets || public_buckets; select string_agg(quote_literal(x), ', ') into public_list from unnest(public_buckets) as x; if exists (select 1 from information_schema.columns where table_schema = 'storage' and table_name = 'objects' and column_name = 'owner_id') then owner_expr := 'owner_id = (select auth.uid())::text'; else owner_expr := 'owner = (select auth.uid())'; end if; for pol in select policyname, roles, cmd, coalesce(qual, '') || ' ' || coalesce(with_check, '') as body from pg_policies where schemaname = 'storage' and tablename = 'objects' loop continue when pol.roles <@ array['service_role']::name[]; continue when pol.policyname like 'storelib owner %'; mentions := null; foreach b in array managed loop if position(quote_literal(b) in pol.body) > 0 then mentions := b; exit; end if; end loop; if mentions is not null or position('bucket_id' in pol.body) = 0 then select string_agg(distinct m[1], ', ') into unmanaged from regexp_matches(pol.body, '''([^'']+)''::text', 'g') as m where not (m[1] = any(managed)) and exists (select 1 from storage.buckets sb where sb.id = m[1]); execute format('drop policy %I on storage.objects', pol.policyname); raise notice 'dropped storage policy "%" (%, roles %)%', pol.policyname, pol.cmd, pol.roles, case when unmanaged is not null then ' - it also named: ' || unmanaged || ', check those buckets still work' else '' end; end if; end loop; for pol in select policyname from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname like 'storelib owner %' loop execute format('drop policy %I on storage.objects', pol.policyname); end loop; execute format( 'create policy %I on storage.objects for select to authenticated using (bucket_id = any (array[%s]) and (public.storage_owns_path(name) or %s))', 'storelib owner read public buckets', public_list, owner_expr); execute format( 'create policy %I on storage.objects for insert to authenticated with check (bucket_id = any (array[%s]) and public.storage_owns_path(name))', 'storelib owner insert public buckets', public_list); execute format( 'create policy %I on storage.objects for update to authenticated using (bucket_id = any (array[%s]) and (public.storage_owns_path(name) or %s)) with check (bucket_id = any (array[%s]) and (public.storage_owns_path(name) or %s))', 'storelib owner update public buckets', public_list, owner_expr, public_list, owner_expr); execute format( 'create policy %I on storage.objects for delete to authenticated using (bucket_id = any (array[%s]) and (public.storage_owns_path(name) or %s))', 'storelib owner delete public buckets', public_list, owner_expr); create policy "storelib owner reserved read digital-products" on storage.objects for select to authenticated using (bucket_id = 'digital-products' and public.storage_reserved_upload(bucket_id, name)); create policy "storelib owner reserved insert digital-products" on storage.objects for insert to authenticated with check (bucket_id = 'digital-products' and public.storage_reserved_upload(bucket_id, name)); create policy "storelib owner reserved update digital-products" on storage.objects for update to authenticated using (bucket_id = 'digital-products' and public.storage_reserved_upload(bucket_id, name)) with check (bucket_id = 'digital-products' and public.storage_reserved_upload(bucket_id, name)); end; $$;
INSERT INTO public.storelib_applied_parts (part, file, sha256) VALUES ('90', '90_storage_policies_needs_owner.sql', 'ddc22cfc130759fbfacb45536938c90e20f1aec09c5d3ee4db92f4450a763149') ON CONFLICT (part) DO UPDATE SET file = excluded.file, sha256 = excluded.sha256, applied_at = now(), applied_by = current_user;

